<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot\Views; use Pterodactyl\Services\Dezerx\DiscordBot\Ui; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\DiscordBot\Format; use Pterodactyl\Services\Dezerx\DiscordBot\Servers; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\ClientApi; class ServerList { public const PER_PAGE = 5; public static function build(ClientApi $api, int $page = 1, ?string $notice = null): array { $listing = Servers::list($api); if ($listing['error'] !== null) { return Cards::error($listing['error']); } $servers = $listing['servers']; $pages = max(1, (int) ceil(count($servers) / self::PER_PAGE)); $page = max(1, min($pages, $page)); $rows = []; foreach (array_slice($servers, ($page - 1) * self::PER_PAGE, self::PER_PAGE) as $server) { $rows[] = [$server, Servers::resources($api, $server)]; } return self::compose($rows, $page, $pages, count($servers), $api->user()->username, $notice); } public static function compose(array $rows, int $page, int $pages, int $total, string $username, ?string $notice = null): array { $style = Style::current(); $online = count(array_filter($rows, fn (array $row) => $row[1]['state'] === 'running')); $components = [ $notice === null ? null : Ui::text($notice), Ui::section( '## ' . ($total === 1 ? 'Your server' : 'Your servers') . "\n" . sprintf('-# %d %s · %d of %d on this page online · %s', $total, $total === 1 ? 'server' : 'servers', $online, count($rows), $style->footer()), Ui::thumbnail($style->logo(BotConfig::panelLogo())) ?? Ui::link(BotConfig::panelUrl(), 'Panel'), ), Ui::divider(), ]; if ($rows === []) { $components[] = Ui::text('**Nothing here yet.** ' . Format::escape($username) . ' has no servers, and is not a subuser on anybody else\'s.'); } foreach ($rows as $index => [$server, $live]) { $components[] = Ui::section( implode("\n", self::lines($server, $live)), Ui::thumbnail($style->logo(Servers::logo($server)), $server['egg']['name'] ?: null), ); if ($index < count($rows) - 1) { $components[] = Ui::divider(false); } } $components[] = Ui::divider(); if (Style::can('controlpanel') && $rows !== []) { $components[] = Ui::row([Ui::select('dzb:open', 'Open a server’s control panel…', array_map(function (array $row) { [$server, $live] = $row; [, $label] = Format::state($live['state']); $address = Servers::primaryAddress($server); return Ui::option( $server['id'], $server['name'], trim($label . ($address !== '' ? ' · ' . $address : '') . ($server['egg']['name'] !== '' ? ' · ' . $server['egg']['name'] : '')), ); }, $rows))]); } $components[] = Ui::row([ Ui::button('dzb:srv:' . ($page - 1), 'Previous', Ui::SECONDARY, $page <= 1), Ui::button('dzb:noop', "Page {$page} of {$pages}", Ui::SECONDARY, true), Ui::button('dzb:srv:' . ($page + 1), 'Next', Ui::SECONDARY, $page >= $pages), Ui::button('dzb:srv:' . $page, 'Refresh', Ui::SECONDARY), Ui::link(BotConfig::panelUrl(), 'Panel'), ]); $components[] = Ui::text('-# Updated ' . Format::timestamp(now()) . (Style::can('controlpanel') ? ' · pick a server for its console and power buttons' : '')); return Ui::message([Ui::container($components, $style->accent())]); } private static function lines(array $server, array $live): array { [$emoji, $label] = Format::state($live['state']); $address = Servers::primaryAddress($server); $details = array_filter([ $address === '' ? null : Format::code($address), $server['egg']['name'] === '' ? null : Format::escape($server['egg']['name']), $server['owner'] ? null : 'shared with you', ]); $lines = ["### {$emoji} " . Format::name($server['name']), implode(' · ', $details) ?: $label]; if ($live['usage'] !== null) { $usage = $live['usage']; $limits = $server['limits']; $stats = [ 'CPU ' . Format::percent($usage['cpu']) . ($limits['cpu'] > 0 ? '/' . $limits['cpu'] . '%' : ''), 'RAM ' . Format::bytes($usage['memory']) . ' / ' . Format::megabytes($limits['memory']), 'Disk ' . Format::bytes($usage['disk']) . ' / ' . Format::megabytes($limits['disk']), ]; if ($live['state'] === 'running' && $usage['uptime'] > 0) { $stats[] = 'up ' . Format::duration($usage['uptime']); } $lines[] = '-# **' . $label . '** · ' . implode(' · ', $stats); } else { $lines[] = '-# **' . $label . '**' . ($live['error'] !== null ? ' · ' . Format::escape(Ui::clip($live['error'], 90)) : ''); } return $lines; } } 